<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
  import {refreshAll} from '$app/navigation';
  import {focusTrap} from '#lib/client/focus-trap.ts';
  import {command,permitted} from '#lib/client/api.ts';
  import {currencyAmount,enteredAmount} from '#lib/client/finance.ts';
  import type {AppData,Row} from '#lib/client/types.ts';
  import Icon from './Icon.svelte';
  let {data}:{data:AppData}=$props();
  let open=$state(false);let kind=$state('receivable');let positiveId=$state('');let negativeId=$state('');let amount=$state('');let reason=$state('');let confirmed=$state(false);let busy=$state(false);let error=$state('');let notice=$state('');
  const amountPattern='[0-9]+([,.][0-9]{1,2})?';
  const items=$derived(data.related?.open_items||[]);
  const positiveItems=$derived(items.filter((item:Row)=>(item.kind||item.target_kind)===kind&&Number(item.outstanding)>0));
  const positive=$derived(positiveItems.find((item:Row)=>item.id===positiveId));
  const negativeItems=$derived(items.filter((item:Row)=>(item.kind||item.target_kind)===kind&&Number(item.outstanding)<0&&(!positive||item.party_id===positive.party_id&&item.currency===positive.currency)));
  const negative=$derived(negativeItems.find((item:Row)=>item.id===negativeId));
  const maximum=$derived(positive&&negative?Math.min(Number(positive.outstanding),Math.abs(Number(negative.outstanding))):null);
  function reset(){positiveId='';negativeId='';amount='';confirmed=false;error='';}
  async function save(event:SubmitEvent){event.preventDefault();if(busy)return;busy=true;error='';try{if(!positive||!negative||!confirmed)throw new Error('Bitte prüfen und bestätigen Sie beide Belege.');const value=enteredAmount(amount);if(!Number.isFinite(value)||value<=0||maximum===null||value>maximum)throw new Error('Der Verrechnungsbetrag muss positiv sein und in beide offenen Restbeträge passen.');await command('finance.credit_offset.create',undefined,{target_kind:kind,positive_id:positiveId,negative_id:negativeId,amount,reason});notice='Die Verrechnung wurde gebucht. Beide offenen Posten wurden entsprechend aktualisiert.';open=false;reset();reason='';await refreshAll().catch(()=>{});}catch(e){error=e instanceof Error?e.message:'Die Verrechnung konnte nicht gebucht werden.';}finally{busy=false;}}
</script>
{#if permitted(data,'finance')}<section class="panel mb"><header class="panel-header"><div><h2>Offene Gutschrift verrechnen</h2><p>Prüfen Sie zwei Belege desselben Geschäftspartners und buchen Sie den vereinbarten Ausgleich.</p></div><button class="btn primary" onclick={()=>{reset();open=true;}}>Verrechnung vorbereiten<Icon name="arrow" size={16}/></button></header>{#if notice}<div class="panel-body"><div class="notice info" role="status"><Icon name="check"/><div>{notice}</div></div></div>{/if}</section>{/if}
{#if open}<div class="modal-backdrop" role="presentation"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="offset-title" tabindex="-1" use:focusTrap onkeydown={e=>{if(e.key==='Escape'&&!busy)open=false;}}><header class="modal-header"><div><h2 id="offset-title">Gutschrift verrechnen</h2><p>Es wird erst mit Ihrer ausdrücklichen Bestätigung gebucht.</p></div><button class="icon-button" aria-label="Schließen" disabled={busy} onclick={()=>open=false}><Icon name="close"/></button></header><form onsubmit={save} style="display:contents"><div class="modal-body">{#if error}<div class="notice error" role="alert">{error}</div>{/if}<div class="field-grid"><div class="field full"><label for="offset-kind">Bereich *</label><select use:searchableSelect={kind} id="offset-kind" bind:value={kind} onchange={reset}><option value="receivable">Kundenforderung & Kundengutschrift</option><option value="payable">Lieferantenverbindlichkeit & Lieferantengutschrift</option></select></div><div class="field full"><label for="offset-positive">Offener positiver Beleg *</label><select use:searchableSelect={positiveId} id="offset-positive" bind:value={positiveId} onchange={()=>{negativeId='';confirmed=false;}} required><option value="">Beleg auswählen</option>{#each positiveItems as item}<option value={item.id}>{item.document_number||'Offener Beleg'} · {item.party_name} · offen {currencyAmount(item.outstanding,item.currency)}</option>{/each}</select><span class="field-help">Wählen Sie den Beleg, dessen offener Betrag durch die Gutschrift verringert werden soll.</span></div><div class="field full"><label for="offset-negative">Dazugehörige offene Gutschrift *</label><select use:searchableSelect={negativeId} id="offset-negative" bind:value={negativeId} onchange={()=>confirmed=false} required disabled={!positive}><option value="">Gutschrift auswählen</option>{#each negativeItems as item}<option value={item.id}>{item.document_number||'Offene Gutschrift'} · {item.party_name} · {currencyAmount(item.outstanding,item.currency)}</option>{/each}</select><span class="field-help">Angezeigt werden offene Gutschriften desselben Geschäftspartners in derselben Währung.</span></div><div class="field"><label for="offset-amount">Vereinbarter Verrechnungsbetrag *</label><input id="offset-amount" bind:value={amount} inputmode="decimal" pattern={amountPattern} required oninput={()=>confirmed=false}/><span class="field-help">Zum Beispiel 125,00.{#if maximum!==null} Höchstens {currencyAmount(maximum,positive?.currency)} für diese beiden Belege.{/if}</span></div><div class="field full"><label for="offset-reason">Vereinbarung / Grundlage *</label><textarea id="offset-reason" bind:value={reason} required minlength="5" placeholder="Zum Beispiel: Verrechnung der Gutschrift mit der bezeichneten Rechnung gemäß Vereinbarung vom …"></textarea></div></div>{#if positive&&negative&&amount}<div class="action-preview mt"><h3>{positive.party_name}</h3><p class="small mt">{positive.document_number} wird mit {negative.document_number} verrechnet.</p><p class="mt"><strong>{currencyAmount(enteredAmount(amount),positive.currency)}</strong></p><p class="field-help mt">Die Buchung dokumentiert den Belegausgleich. Eine Auszahlung oder Banküberweisung wird dadurch nicht ausgelöst.</p></div>{/if}{#if !items.length}<div class="notice info mt"><Icon name="file"/><div>Es sind noch keine geeigneten offenen Belege verfügbar. Prüfen Sie die bestätigten Forderungen bzw. Verbindlichkeiten und die zugehörige Gutschrift.</div></div>{/if}<label class="check-field mt"><input type="checkbox" bind:checked={confirmed} required/><span>Ich habe beide Belege, Geschäftspartner, Währung und Betrag geprüft und bestätige diese Verrechnung.</span></label></div><footer class="modal-footer"><button class="btn" type="button" disabled={busy} onclick={()=>open=false}>Abbrechen</button><button class="btn primary" disabled={busy||!confirmed||!positive||!negative}>{busy?'Wird gebucht …':'Verrechnung verbindlich buchen'}</button></footer></form></div></div>{/if}
